class _TasbeehPageState extends State<TasbeehPage>{final dhikrList=['سبحان الله','الحمد لله','الله أكبر','لا إله إلا الله','أستغفر الله','اللهم صلِّ على سيدنا محمد'];String selectedDhikr='سبحان الله';Map<String,int> counters={};Map<String,int> todayCounters={};String todayKey='';@override void initState(){super.initState();todayKey=_dayKey(DateTime.now());for(final d in dhikrList){counters[d]=0;todayCounters[d]=0;}loadCounters();}String _dayKey(DateTime d)=>'${d.year}-${d.month}-${d.day}';Future<void> loadCounters()async{final p=await SharedPreferences.getInstance();if((p.getString('tasbeeh_day')??todayKey)!=todayKey){for(final d in dhikrList){await p.setInt('today_counter_$d',0);}await p.setString('tasbeeh_day',todayKey);}setState((){for(final d in dhikrList){counters[d]=p.getInt('counter_$d')??0;todayCounters[d]=p.getInt('today_counter_$d')??0;}selectedDhikr=p.getString('selected_dhikr')??dhikrList.first;});}Future<void> save()async{final p=await SharedPreferences.getInstance();await p.setInt('counter_$selectedDhikr',counters[selectedDhikr]??0);await p.setInt('today_counter_$selectedDhikr',todayCounters[selectedDhikr]??0);await p.setString('tasbeeh_day',todayKey);await p.setString('selected_dhikr',selectedDhikr);}int get current=>counters[selectedDhikr]??0;int get today=>todayCounters[selectedDhikr]??0;@override Widget build(BuildContext context)=>Padding(padding:const EdgeInsets.all(16),child:Column(children:[DropdownButtonFormField<String>(value:selectedDhikr,decoration:const InputDecoration(labelText:'اختر الذكر',border:OutlineInputBorder()),items:dhikrList.map((d)=>DropdownMenuItem(value:d,child:Text(d))).toList(),onChanged:(v)async{if(v==null)return;setState(()=>selectedDhikr=v);await save();}),const SizedBox(height:18),Row(children:[Expanded(child:_stat('اليوم',today)),const SizedBox(width:10),Expanded(child:_stat('الإجمالي',current))]),const SizedBox(height:22),Text(selectedDhikr,style:const TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const SizedBox(